<div class="page-actions"><form class="filter-bar" method="get"><input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Buscar código, título o dirección"><select class="form-select" name="category"><option value="">Todas las categorías</option><?php foreach(['seguridad'=>'Seguridad','barrio'=>'Barrio','emergencia'=>'Emergencia','mascota'=>'Mascota'] as $value=>$label):?><option value="<?= $value ?>" <?= $filters['category']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select><select class="form-select" name="status"><option value="">Todos los estados</option><?php foreach(['nuevo','validando','asignado','en_proceso','resuelto','cerrado'] as $status):?><option value="<?= $status ?>" <?= $filters['status']===$status?'selected':'' ?>><?= ucfirst(str_replace('_',' ',$status)) ?></option><?php endforeach;?></select><button class="btn btn-outline-primary">Filtrar</button></form><a class="btn btn-danger" href="<?= url('reportes/nuevo') ?>">+ Nuevo reporte</a></div>
<div class="card table-card"><div class="table-responsive"><table class="table"><thead><tr><th>Código</th><th>Reporte</th><th>Ubicación</th><th>Prioridad</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php if(!$reports):?><tr><td colspan="6" class="empty-state">No se encontraron reportes.</td></tr><?php endif;?><?php foreach($reports as $report):?><tr data-href="<?= url('reportes/'.$report['id']) ?>"><td><a href="<?= url('reportes/'.$report['id']) ?>"><strong><?= e($report['public_code']) ?></strong></a></td><td><span class="category-pill" style="--pill:<?= e($report['color']) ?>"><?= e($report['type_name']) ?></span><strong class="d-block mt-1"><?= e($report['title']) ?></strong></td><td><?= e($report['address']?:$report['commune_name']) ?></td><td><span class="priority priority-<?= e($report['priority']) ?>"><?= e($report['priority']) ?></span></td><td><span class="badge bg-<?= report_badge($report['status']) ?>"><?= e(str_replace('_',' ',$report['status'])) ?></span></td><td><?= e(date('d/m/Y H:i',strtotime($report['created_at']))) ?></td></tr><?php endforeach;?></tbody></table></div></div>

